-- =============================================================
-- MOCKAROO DATA - comprehensive seed for all user-facing tables
-- ~10 users per persona, each well-populated with unique data.
-- Loads after every schema (02, 03, 04, 07) so all FKs resolve.
--
-- Covers the users table plus the 7 tables that reference it:
--   household_profiles, saved_articles, snapshots, notes,
--   trader_watchlist, trader_price_alerts, trader_trade_notes
--
-- Journalist snapshot/note CONTEXT metrics are computed from the real
-- gas-storage data (06) and the ML2 logistic-regression weights (03),
-- replicating the API (storage_service + gas_storage_model). They match
-- what the live app shows for each country -- not placeholder numbers.
--
-- ML / prediction / visualization tables are NOT touched here:
--   gas_storage_daily, gas_storage_winters, gas_storage_model,
--   and the ML1 price-prediction tables in 05_price_prediction.sql.
--
-- user_id ranges: household_owner 1-10, journalist 11-20, energy_trader 21-30.
-- =============================================================

USE Zeus;

-- -------------------------------------------------------------
-- USERS
-- -------------------------------------------------------------

-- -------------------------------------------------------------
-- HOUSEHOLD_PROFILES - one billing profile per owner
-- -------------------------------------------------------------
    user_id, utility_provider, monthly_bill_amount, bill_due_date,
    billing_frequency, avg_monthly_kwh, tariff_type, notes
) VALUES
